/**
 * Returns the top trending coins validated against CoinGecko gainers, OKX USDT SWAP instruments (for candle data), and Phemex USDT-perp listing (for trading). Updated every 4 hours. Coins expire after 8 hours (cooldown window preserves active-trade context after a coin drops out of the gainers list).
 * @summary Get currently-trending coins discovered from CoinGecko gainers + OKX
 */
export const GetTrendingSymbolsResponse = zod.object({
  symbols: zod.array(
    zod
      .object({
        symbolKey: zod.string().describe("Internal symbol key (e.g. TONUSDT)"),
        baseAsset: zod.string().describe("Base ticker (e.g. TON)"),
        okxSymbol: zod
          .string()
          .describe("OKX SWAP instrument ID (e.g. TON-USDT-SWAP)"),
        phemexSymbol: zod
          .string()
          .describe("Phemex perp symbol (e.g. TONUSDT)"),
        decimals: zod.number(),
        priceChange24h: zod.number().describe("24-hour price change percent"),
        rank: zod
          .number()
          .describe("Rank among current trending coins (1 = top gainer)"),
        discoveredAt: zod.string(),
        expiresAt: zod.string(),
      })
      .describe(
        "A dynamically-discovered trending coin with an OKX USDT SWAP instrument.",
      ),
  ),
  lastUpdated: zod.string(),
});

/**
 * Returns the public half of the VAPID keypair used to sign Web Push payloads. The browser passes this to PushManager.subscribe() before posting the resulting subscription back via /push/subscribe.
 * @summary Get the server's VAPID public key for browser subscription
 */
export const GetVapidPublicKeyResponse = zod.object({
  publicKey: zod
    .string()
    .describe(
      "Base64URL-encoded VAPID public key suitable for PushManager.subscribe applicationServerKey",
    ),
});

/**
 * Stores a Web Push subscription so the server can fan out signal alerts to it. Idempotent — re-posting the same endpoint upserts the existing record.
 * @summary Register a browser Web Push subscription
 */
export const SubscribePushBody = zod.object({
  endpoint: zod
    .string()
    .describe("Push service endpoint URL (FCM \/ APNs gateway)"),
  keys: zod.object({
    p256dh: zod
      .string()
      .describe("Browser-supplied P-256 ECDH public key (base64url)"),
    auth: zod.string().describe("Browser-supplied auth secret (base64url)"),
  }),
  userAgent: zod
    .string()
    .optional()
    .describe("Optional User-Agent string for diagnostics"),
});

export const SubscribePushResponse = zod.object({
  ok: zod.boolean(),
});

/**
 * Deletes the subscription matching the supplied endpoint. Safe to call when no matching row exists.
 * @summary Remove a browser Web Push subscription
 */
export const UnsubscribePushBody = zod.object({
  endpoint: zod.string(),
});

export const UnsubscribePushResponse = zod.object({
  ok: zod.boolean(),
});

/**
 * Returns historically closed trades logged by the signal engine (SL hits, TP2 hits, BE-trail closes, direction reversals, and missed pending orders).
 * @summary Closed trade history with P&L tracking
 */
export const getTradeHistoryQueryLimitDefault = 100;
export const getTradeHistoryQueryLimitMax = 500;

export const GetTradeHistoryQueryParams = zod.object({
  symbol: zod.coerce
    .string()
    .optional()
    .describe(
      "Filter by symbol key (e.g. XAGUSD). Returns all symbols if omitted.",
    ),
  limit: zod.coerce
    .number()
    .min(1)
    .max(getTradeHistoryQueryLimitMax)
    .default(getTradeHistoryQueryLimitDefault)
    .describe("Maximum number of records to return, newest first."),
});

export const GetTradeHistoryResponse = zod.object({
  trades: zod.array(
    zod.object({
      id: zod.number(),
      key: zod.string().describe("Composite key (e.g. XAGUSD::1h)"),
      symbol: zod.string(),
      timeframe: zod.string(),
      signal: zod.enum(["BUY", "SELL"]),
      signalType: zod.enum(["FIB50_SWING", "DOUBLE_TOP"]),
      entryPrice: zod.number(),
      stopLoss: zod.number(),
      takeProfit1: zod.number(),
      takeProfit2: zod.number(),
      riskRewardRatio: zod.number(),
      exitPrice: zod.number(),
      outcome: zod
        .enum(["SL", "BE_TRAIL", "TP2", "REVERSED", "MISSED"])
        .describe(
          "SL=stop hit, BE_TRAIL=closed flat after TP1 trail, TP2=full target, REVERSED=signal flipped, MISSED=pending never filled",
        ),
      rMultiple: zod
        .number()
        .describe("Profit\/loss in units of initial risk (R)"),
      tp1Hit: zod
        .boolean()
        .describe("Whether TP1 was reached before the trade closed"),
      openedAt: zod
        .number()
        .optional()
        .describe("Unix ms timestamp when the signal was first staged"),
      closedAt: zod
        .number()
        .describe("Unix ms timestamp when the trade was closed"),
    }),
  ),
  totalTrades: zod.number(),
  totalR: zod
    .number()
    .describe(
      "Cumulative R-multiple across all returned trades (excludes MISSED)",
    ),
  winCount: zod
    .number()
    .describe("Trades that closed at TP2 or BE_TRAIL (partial win)"),
  lossCount: zod.number().describe("Trades that hit the full SL"),
  lastUpdated: zod.string(),
});

/**
 * Returns a permanent record of every BUY/SELL signal that fired, including TP1, TP2, SL levels. Unlike closed_trades this log is never deleted — signals that were lost due to server restarts or missed eviction are still here.
 * @summary Append-only log of every fired signal
 */
export const getSignalLogQueryLimitDefault = 200;
export const getSignalLogQueryLimitMax = 500;

export const GetSignalLogQueryParams = zod.object({
  symbol: zod.coerce
    .string()
    .optional()
    .describe(
      "Filter by symbol key (e.g. ZECUSD). Returns all symbols if omitted.",
    ),
  limit: zod.coerce
    .number()
    .min(1)
    .max(getSignalLogQueryLimitMax)
    .default(getSignalLogQueryLimitDefault)
    .describe("Maximum number of records to return, newest first."),
});

export const GetSignalLogResponse = zod.object({
  entries: zod.array(
    zod.object({
      id: zod.number(),
      key: zod.string().describe("Composite key (e.g. ZECUSD::1h)"),
      symbol: zod.string(),
      timeframe: zod.string(),
      signal: zod.enum(["BUY", "SELL"]),
      signalType: zod.enum(["FIB50_SWING", "DOUBLE_TOP"]),
      entryPrice: zod.number(),
      stopLoss: zod.number(),
      takeProfit1: zod.number(),
      takeProfit2: zod.number(),
      riskRewardRatio: zod.number(),
      signalReason: zod.string(),
      firedAt: zod.number().describe("Unix ms timestamp when the signal fired"),
    }),
  ),
  total: zod.number(),
  lastUpdated: zod.string(),
});

